using System;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class WindDesignForm {
 DataGridView staadProfile,staadWalls,staadFaces;TextBox staadCommands;Label staadStatus;
 readonly DataGridView[] exposureAuditGrids=new DataGridView[8],topographicAuditGrids=new DataGridView[8];readonly Label[] auditReasons=new Label[8];
 static DataGridView ReadOnlyGrid(params string[] headers){var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells};foreach(string header in headers)grid.Columns.Add(header,header);grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;GridAppearance.Apply(grid);return grid;}
 static string GridText(DataGridView grid,string separator){Func<string,string> quote=value=>separator==","?"\""+(value??"").Replace("\"","\"\"")+"\"":(value??"").Replace("\t"," ").Replace("\r"," ").Replace("\n"," ");var b=new StringBuilder();b.AppendLine(string.Join(separator,grid.Columns.Cast<DataGridViewColumn>().Select(c=>quote(c.HeaderText))));foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow)b.AppendLine(string.Join(separator,row.Cells.Cast<DataGridViewCell>().Select(c=>quote(Convert.ToString(c.Value,CultureInfo.InvariantCulture)))));return b.ToString();}
 void AddAuditPage(){var page=new TabPage("Exposure and Kzt explanation");var directions=new NavigationTabs{Dock=DockStyle.Fill};for(int i=0;i<8;i++){var direction=new TabPage("Wind from "+WindAssessment.Directions[i]);var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5};split.RowStyles.Add(new RowStyle(SizeType.Absolute,30));split.RowStyles.Add(new RowStyle(SizeType.Percent,48));split.RowStyles.Add(new RowStyle(SizeType.Absolute,58));split.RowStyles.Add(new RowStyle(SizeType.Absolute,30));split.RowStyles.Add(new RowStyle(SizeType.Percent,52));exposureAuditGrids[i]=ReadOnlyGrid("Check","Value","Basis / decision");topographicAuditGrids[i]=ReadOnlyGrid("Check","Value","Basis / decision");foreach(var g in new[]{exposureAuditGrids[i],topographicAuditGrids[i]}){g.Columns[0].FillWeight=26;g.Columns[1].FillWeight=22;g.Columns[2].FillWeight=52;}auditReasons[i]=new Label{Dock=DockStyle.Fill,Padding=new Padding(6),Font=ModernUi.Strong};
   split.Controls.Add(new Label{Text="Exposure category - mapped surface roughness in the two 45° upwind sectors",Dock=DockStyle.Fill,Font=ModernUi.Strong},0,0);split.Controls.Add(exposureAuditGrids[i],0,1);split.Controls.Add(auditReasons[i],0,2);split.Controls.Add(new Label{Text="Topographic factor Kzt - NSCP 2015 Section 207A.8.1 conditions and substitution",Dock=DockStyle.Fill,Font=ModernUi.Strong},0,3);split.Controls.Add(topographicAuditGrids[i],0,4);direction.Controls.Add(split);directions.TabPages.Add(direction);}
  page.Controls.Add(directions);AddResultPage(page);}
 void UpdateAuditViews(List<WindDirection> values){for(int i=0;i<8;i++){if(exposureAuditGrids[i]==null)continue;exposureAuditGrids[i].Rows.Clear();topographicAuditGrids[i].Rows.Clear();auditReasons[i].Text=values==null?"Load site terrain to explain the exposure and Kzt for this direction.":"";if(values==null)continue;var d=values[i];{/* the tab follows the assessed bearing (a building face or diagonal) */var tab=exposureAuditGrids[i].Parent!=null?exposureAuditGrids[i].Parent.Parent as TabPage:null;if(tab!=null)tab.Text="Wind from "+d.Name;}if(d.ExposureAudit!=null)foreach(var row in d.ExposureAudit.Checks)exposureAuditGrids[i].Rows.Add(row.Cast<object>().ToArray());auditReasons[i].Text="Exposure "+d.Exposure+";  Kzt = "+F(d.Kzt)+".  "+d.TopographicReason;foreach(var row in d.TopographicChecks)topographicAuditGrids[i].Rows.Add(row.Cast<object>().ToArray());}}
 void AddStaadWindPage(){var root=new TabPage("STAAD Wind Input");var nested=new NavigationTabs{Dock=DockStyle.Fill};staadProfile=ReadOnlyGrid("Wind from","Exposure","Height above ground z (m)","Kz","Kzt(z)","Velocity pressure qz (kN/m²)");staadWalls=ReadOnlyGrid("Wind from / building axis","Band top height (m)","Windward wall qz·G·Cp (kN/m²)","Leeward wall qh·G·Cp (kN/m²)","STAAD intensity INT = windward + |leeward| (kN/m²)");
  staadFaces=ReadOnlyGrid("Load case","Face","Height / zone","Cp","External q·G·Cp (kN/m²)","Internal −qi·GCpi (kN/m²)","Net p (kN/m²)","STAAD face and load direction");staadCommands=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font("Consolas",10)};staadStatus=new Label{Dock=DockStyle.Top,Height=46,Padding=new Padding(8),ForeColor=PowTheme.Muted};root.Controls.Add(nested);root.Controls.Add(staadStatus);
  string[] titles={"Height and velocity pressure qz","Wall pressures for STAAD","Pressures on every face","STAAD DEFINE WIND LOAD commands"};string[] notes={"Velocity pressure qz = 0.613 Kz Kzt Kd V² by height for each wind-from direction, including eave, mean roof and apex heights. qz is NOT a surface pressure: multiply by G and Cp. Use this table only when STAAD generates the surface pressures itself.","Design wall pressures by height band for each principal building axis. Windward pressure is evaluated at the top of each band (conservative); leeward suction uses qh. Internal pressure cancels across opposite walls. Roof pressures are in the Building pressures tab and are applied separately.","Every face of every load case: in one wind direction the windward wall (by height), the leeward wall, both side walls and the roof all have different pressures. (a) = +GCpi, (b) = −GCpi. The STAAD intensity (INT) covers only windward + leeward walls; apply the side walls and the roof as member loads: net p × tributary width (positive toward the surface, negative away).","DEFINE WIND LOAD with one type per face for each wind direction: WW (windward, by height), LW (leeward) and SW (side walls), named W1 WW FROM SW etc. INT = external q·G·Cp (kN/m², positive magnitude); WW pushes on the wall, LW and SW are suction. INT applies from the previous HEIG up to each HEIG (from the base). Make your own load cases with these types; add the internal pressure listed per direction where your case needs it. Do not apply G and Cp again in STAAD."};
  Control[] bodies={staadProfile,staadWalls,staadFaces,staadCommands};
  for(int i=0;i<4;i++){var page=new TabPage(titles[i]);var commands=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(4)};var body=bodies[i];var copy=new Button{Text=i==3?"Copy commands":"Copy table",AutoSize=true};copy.Click+=(s,e)=>{string text=body is TextBox?((TextBox)body).Text:GridText((DataGridView)body,"\t");if(text.Trim()!="")Clipboard.SetText(text);};commands.Controls.Add(copy);
   if(i<3){var export=new Button{Text="Export CSV",AutoSize=true};var grid=(DataGridView)body;export.Click+=(s,e)=>{using(var dialog=new SaveFileDialog{Filter="CSV table|*.csv",FileName=grid==staadProfile?"STAAD-Wind-Height-Pressure.csv":grid==staadFaces?"STAAD-Wind-Face-Pressures.csv":"STAAD-Wind-Wall-Pressures.csv"})if(dialog.ShowDialog(this)==DialogResult.OK)File.WriteAllText(dialog.FileName,GridText(grid,","),new UTF8Encoding(true));};commands.Controls.Add(export);}
   var note=new Label{Dock=DockStyle.Bottom,Height=70,Padding=new Padding(10),Text=notes[i]};page.Controls.Add(body);page.Controls.Add(note);page.Controls.Add(commands);nested.TabPages.Add(page);}
  AddResultPage(root);}
 void RefreshStaadWind(){if(staadProfile==null)return;double speed;try{speed=WindTin.At(Number("Latitude"),Number("Longitude"),Value("Category")).V;}catch{staadProfile.Rows.Clear();staadWalls.Rows.Clear();staadFaces.Rows.Clear();staadCommands.Text="";staadStatus.Text="Enter valid site coordinates to produce STAAD wind data.";return;}UpdateStaadWindInputs(speed);}
 void UpdateStaadWindInputs(double speed){if(staadProfile==null)return;staadProfile.Rows.Clear();staadWalls.Rows.Clear();staadFaces.Rows.Clear();staadCommands.Text="";WindBuildingInput building;
  if(terrain==null){staadStatus.Text="Load site terrain first. STAAD wind data needs the exposure and Kzt of each direction.";return;}
  if(!TryBuildingGeometry(out building)){staadStatus.Text="Enter the building width, length, eave and apex heights on the Building pressures tab to produce STAAD wind data.";return;}
  try{building.Kd=Number("Kd");var directions=WindAssessment.Calculate(terrain,building.Height,speed,building.Kd,building.Height);foreach(var row in WindStaadInput.Profile(building,speed,building.Kd,directions))staadProfile.Rows.Add(row.Direction,row.Exposure,F(row.Height),F(row.Kz),F(row.Kzt),F(row.Qz));
   if(!BuildingEnabled){staadStatus.Text="qz profile shown. Turn on building pressures to produce wall intensities and STAAD commands.";return;}var bands=WindStaadInput.WallBands(Building(),speed,directions);foreach(var band in bands)staadWalls.Rows.Add(band.Axis,F(band.Top),F(band.Windward),F(band.Leeward),F(band.Combined));var bb=Building();double xb=StaadBearing();foreach(var row in WindStaadInput.FacePressures(bb,speed,directions,xb))staadFaces.Rows.Add(row.Cast<object>().ToArray());/* the wind cases of the Load Combinations sheet use these TYPE numbers */try{var types=WindStaadInput.FaceTypes(bb,speed,directions,xb);if(types.Count>0)DesignLoadsLink.Set("wind-staad",types.ToDictionary(x=>x.Travel,x=>x.Pack()));}catch(Exception){}staadCommands.Text=StaadLines.Wrap(WindStaadInput.FaceCommands(bb,speed,directions,xb)).Replace("\n","\r\n");
   int unresolved=directions.Count(d=>d.Exposure=="Unresolved"||!WindTin.Finite(d.Kzt));staadStatus.Text=unresolved>0?unresolved+" direction(s) are unresolved and are left out; review terrain before using STAAD data.":"STAAD wind data ready. Units: m and kN/m².";staadStatus.ForeColor=unresolved>0?Color.Firebrick:PowTheme.Teal;}
  catch(Exception ex){staadStatus.Text="STAAD wind data unavailable: "+ex.Message;staadStatus.ForeColor=Color.Firebrick;}}
}
}
